LOCATIONS = [
    {"key": "matterhorn", "name": "Le Cervin (Matterhorn)", "canton": "Valais",
     "texte": "Le Cervin refuse de se laisser photographier deux fois de la même façon. "
              "Il suffit d'un nuage, d'un degré de moins, et la montagne change de visage."},
    {"key": "oeschinensee", "name": "Oeschinensee", "canton": "Berne",
     "texte": "L'eau y garde la couleur du glacier qui la nourrit : un bleu qui ne s'invente pas."},
    {"key": "lauterbrunnen", "name": "Lauterbrunnen", "canton": "Berne",
     "texte": "Soixante-douze cascades dans une vallée si étroite que le ciel semble une fissure."},
    {"key": "lavaux", "name": "Les terrasses de Lavaux", "canton": "Vaud",
     "texte": "Huit siècles de murs de pierre pour domestiquer une pente. Et le Léman, toujours, en contrebas."},
    {"key": "engadine", "name": "La vallée de l'Engadine", "canton": "Grisons",
     "texte": "En hiver, le lac gelé craque comme un vieux navire. On entend la montagne travailler."},
    {"key": "aare", "name": "Les gorges de l'Aar", "canton": "Berne",
     "texte": "L'eau a mis dix mille ans à sculpter ce couloir. Elle continue, sans se presser."},
    {"key": "grindelwald", "name": "Grindelwald et l'Eiger", "canton": "Berne",
     "texte": "La face nord de l'Eiger ne se laisse jamais voir deux fois pareille. "
              "Un nuage s'y accroche, et toute la vallée change de lumière."},
    {"key": "aletsch", "name": "Le glacier d'Aletsch", "canton": "Valais",
     "texte": "Vingt-trois kilomètres de glace, la plus longue des Alpes. À cette échelle, "
              "le paysage devient une question de temps plutôt que de beauté."},
    {"key": "verzasca", "name": "La Verzasca", "canton": "Tessin",
     "texte": "Le granit a été poli par l'eau jusqu'à devenir une pierre douce. "
              "L'émeraude de la rivière n'a besoin d'aucun filtre."},
    {"key": "creux-du-van", "name": "Le Creux du Van", "canton": "Neuchâtel",
     "texte": "Un cirque de calcaire d'un kilomètre de large, creusé dans le Jura. "
              "Quand la brume monte, on croit regarder un autre pays."},
    {"key": "chillon", "name": "Le château de Chillon", "canton": "Vaud",
     "texte": "Neuf siècles posés sur un rocher, au bord du Léman. Le matin, l'eau est "
              "si calme que le château s'y répète à l'identique."},
    {"key": "seealpsee", "name": "Le Seealpsee", "canton": "Appenzell Rhodes-Intérieures",
     "texte": "Un lac d'alpage immobile dans l'Alpstein, des chalets de bois noirci, "
              "et des parois calcaires qui tombent droit dans l'eau."},
    {"key": "brienz", "name": "Le lac de Brienz", "canton": "Berne",
     "texte": "Une eau laiteuse, couleur de farine de glacier, butant contre des falaises "
              "que la forêt n'a jamais réussi à quitter."},
    {"key": "rhine-falls", "name": "Les chutes du Rhin", "canton": "Schaffhouse",
     "texte": "Le plus grand chute d'Europe en volume. On n'entend plus rien à vingt mètres, "
              "et les embruns montent comme une fumée."},
    {"key": "gruyeres", "name": "Gruyères", "canton": "Fribourg",
     "texte": "Une colline, un château, des prés ondulés. Le paysage suisse dans ce qu'il a "
              "de plus simple, et de plus difficile à bien photographier."},
    {"key": "saas-fee", "name": "Saas-Fee", "canton": "Valais",
     "texte": "Un village cerné par les glaciers, ses mélèzes dorés et ses maisons de bois "
              "noirci par trois cents hivers."},
    {"key": "morteratsch", "name": "Le glacier de Morteratsch", "canton": "Grisons",
     "texte": "Un glacier qui recule d'une quarantaine de mètres par an. La photo dit aussi "
              "quelque chose qu'on préférerait ne pas voir."},
    {"key": "titlis", "name": "Le massif du Titlis", "canton": "Obwald",
     "texte": "À l'aube, la neige prend une teinte rose qu'aucun écran ne restitue vraiment. "
              "En dessous, la mer de nuages attend le soleil."},
    {"key": "pilatus", "name": "Le Pilatus", "canton": "Nidwald",
     "texte": "La montagne veille sur le lac des Quatre-Cantons. Le soir, sa crête se découpe "
              "en sombre sur un ciel qui n'en finit pas de s'éteindre."},
    {"key": "areuse", "name": "Les gorges de l'Areuse", "canton": "Neuchâtel",
     "texte": "Un couloir de calcaire et de mousse où l'eau prend la couleur du vert profond. "
              "On y descend au frais, même en plein été."},
    {"key": "lac-de-joux", "name": "Le lac de Joux", "canton": "Vaud",
     "texte": "En hiver, la glace craque et chante sur toute la surface. Le Jura devient alors "
              "un paysage polaire à une heure de Lausanne."},
    {"key": "blausee", "name": "Le Blausee", "canton": "Berne",
     "texte": "Un bleu si net qu'on voit les troncs au fond de l'eau. Petit lac, grande "
              "réputation : il faut arriver avant que la lumière ne durcisse."},
    {"key": "ascona", "name": "Le lac Majeur et Ascona", "canton": "Tessin",
     "texte": "La Suisse qui regarde l'Italie. Palmiers, toits de tuiles, montagnes qui tombent "
              "droit dans l'eau : un autre pays à deux heures de train."},
    {"key": "gstaad", "name": "Le Saanenland et Gstaad", "canton": "Berne",
     "texte": "Des chalets de bois noirci, des prés en pente, des vaches qui savent l'heure. "
              "Le paysage suisse dans son évidence la plus calme."},
    {"key": "arosa", "name": "Le lac d'Arosa", "canton": "Grisons",
     "texte": "Un lac sombre au pied de parois verticales, entouré de mélèzes qui passent à l'or "
              "en trois jours d'octobre."},
    {"key": "val-ferret", "name": "Le Val Ferret", "canton": "Valais",
     "texte": "Une vallée qui s'ouvre jusqu'aux glaciers du Grand Combin. En automne, les "
              "mélèzes y mettent une lumière de fin du monde."},
]

