# --------------------------------------------------------------------------
# BASE DE DONNÉES
# --------------------------------------------------------------------------
LOCK = threading.Lock()


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def db():
    conn = sqlite3.connect(DB_PATH, timeout=20, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    return conn


SCHEMA = """
CREATE TABLE IF NOT EXISTS products (
  id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL,
  kind TEXT NOT NULL, price_cents INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'CHF',
  description TEXT, image_key TEXT, payment_url TEXT DEFAULT '', active INTEGER DEFAULT 1,
  created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders (
  id INTEGER PRIMARY KEY AUTOINCREMENT, ref TEXT UNIQUE NOT NULL, product_id INTEGER,
  amount_cents INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'CHF', status TEXT DEFAULT 'pending',
  source TEXT DEFAULT 'demo', buyer_email TEXT, license_token TEXT, created_at TEXT NOT NULL,
  paid_at TEXT);
CREATE TABLE IF NOT EXISTS posts (
  id INTEGER PRIMARY KEY AUTOINCREMENT, location_key TEXT NOT NULL, location_name TEXT NOT NULL,
  canton TEXT NOT NULL, caption TEXT NOT NULL, scheduled_for TEXT NOT NULL, status TEXT DEFAULT 'queued',
  published_at TEXT, permalink TEXT, error TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (
  id INTEGER PRIMARY KEY AUTOINCREMENT, level TEXT DEFAULT 'info', message TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);
"""


def init_db():
    conn = db()
    try:
        with LOCK:
            conn.executescript(SCHEMA)
            conn.commit()
    finally:
        conn.close()


def q(sql, params=()):
    conn = db()
    try:
        return [dict(r) for r in conn.execute(sql, params).fetchall()]
    finally:
        conn.close()


def q1(sql, params=()):
    rows = q(sql, params)
    return rows[0] if rows else None


def x(sql, params=()):
    conn = db()
    try:
        with LOCK:
            cur = conn.execute(sql, params)
            conn.commit()
            return cur.lastrowid
    finally:
        conn.close()


def admin_token():
    """Jeton d'accès au tableau de bord, conservé entre les lancements."""
    tok = setting("admin_token", "")
    if not tok:
        tok = secrets.token_urlsafe(6)
        set_setting("admin_token", tok)
    return tok


def setting(key, default=""):
    row = q1("SELECT value FROM settings WHERE key=?", (key,))
    return row["value"] if row and row["value"] is not None else default


def set_setting(key, value):
    x("INSERT INTO settings(key,value) VALUES(?,?) "
      "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (key, str(value)))


def log(level, message):
    try:
        x("INSERT INTO events(level,message,created_at) VALUES(?,?,?)", (level, message[:1200], now_iso()))
    except Exception:
        pass


# --------------------------------------------------------------------------
# CONTENU
# --------------------------------------------------------------------------
def recent_locations(limit=8):
    """Les lieux publiés ou planifiés le plus récemment, pour éviter les doublons."""
    rows = q("SELECT location_key FROM posts ORDER BY scheduled_for DESC LIMIT ?", (limit,))
    return {r["location_key"] for r in rows}


def plan_for(seed_day: str, index: int = 0, avoid=None) -> dict:
    """Choisit un lieu et une lumière de façon déterministe, sans répéter."""
    h = 0
    for ch in f"{seed_day}-{index}":
        h = (h * 131 + ord(ch)) % 100000
    loc = None
    for k in range(len(LOCATIONS)):
        candidate = LOCATIONS[(h + k + index) % len(LOCATIONS)]
        if not avoid or candidate["key"] not in avoid:
            loc = candidate
            break
    if loc is None:
        loc = LOCATIONS[h % len(LOCATIONS)]
    month = datetime.now().month
    season_fr, season_detail = SEASONS[month]
    light = LIGHTS[(h // 7) % len(LIGHTS)]
    return {"loc": loc, "season": season_fr, "season_detail": season_detail, "light": light}


def build_caption(plan: dict) -> str:
    loc = plan["loc"]
    parts = [
        f"📍 {loc['name']} — {loc['canton']}",
        "",
        loc["texte"],
        f"Lumière : {plan['light']} · Saison : {plan['season']}.",
        "",
        "🖼️ Tirage limité & guides de randonnée → lien en bio",
        "   /bio",
        "",
    ]
    if AI_LABEL:
        parts += ["🤖 Image générée par IA (prompt maison, retouche incluse).", ""]
    parts.append(HASHTAGS)
    return "\n".join(parts)


def ensure_queue(target=QUEUE_DAYS):
    """Maintient `target` publications à venir."""
    if setting("paused", "0") == "1":
        return 0
    rows = q("SELECT scheduled_for FROM posts WHERE status='queued' ORDER BY scheduled_for")
    missing = target - len(rows)
    if missing <= 0:
        return 0
    base = datetime.now().replace(hour=PUBLISH_HOUR, minute=PUBLISH_MIN, second=0, microsecond=0)
    last = rows[-1]["scheduled_for"] if rows else None
    cursor = datetime.fromisoformat(last) if last else base
    if cursor <= datetime.now():
        cursor = base
    created = 0
    for i in range(missing):
        cursor = cursor + timedelta(days=1)
        seed = cursor.strftime("%Y-%m-%d")
        plan = plan_for(seed, created, avoid=recent_locations(10))
        loc = plan["loc"]
        x("INSERT INTO posts(location_key,location_name,canton,caption,scheduled_for,status,created_at) "
          "VALUES(?,?,?,?,?, 'queued', ?)",
          (loc["key"], loc["name"], loc["canton"], build_caption(plan),
           cursor.replace(microsecond=0).isoformat(), now_iso()))
        created += 1
    if created:
        log("info", f"{created} publication(s) planifiée(s) — file à {target} jours")
    return created


def publish_post(post_id):
    post = q1("SELECT * FROM posts WHERE id=?", (post_id,))
    if not post:
        return {"ok": False, "error": "Publication introuvable"}
    if post["status"] == "published":
        return {"ok": True, "already": True, "permalink": post["permalink"]}

    token = setting("ig_token", IG_TOKEN)
    user_id = setting("ig_user_id", IG_USER_ID)
    if not (token and user_id):
        permalink = "https://www.instagram.com/p/" + secrets.token_urlsafe(8)[:11] + "/"
        x("UPDATE posts SET status='published', published_at=?, permalink=? WHERE id=?",
          (now_iso(), permalink, post_id))
        log("info", f"[DÉMO] Publication simulée : {post['location_name']}")
        return {"ok": True, "mode": "demo", "permalink": permalink}

    # --- publication réelle (API Instagram with Instagram Login) -------------
    public = setting("public_url", "").rstrip("/")
    if not public:
        msg = ("Le site doit être EN LIGNE (choix 2 au démarrage) : Instagram "
               "télécharge l'image depuis une adresse publique.")
        x("UPDATE posts SET status='failed', error=? WHERE id=?", (msg, post_id))
        log("error", msg)
        return {"ok": False, "error": msg}
    try:
        api = "https://graph.instagram.com/v23.0"
        image_url = f"{public}/img/{post['location_key']}"
        data = urllib.parse.urlencode({
            "image_url": image_url, "caption": post["caption"], "access_token": token,
        }).encode()
        req = urllib.request.Request(f"{api}/{user_id}/media", data=data)
        with urllib.request.urlopen(req, timeout=60) as r:
            container = json.loads(r.read())["id"]
        for _ in range(30):
            time.sleep(3)
            u = f"{api}/{container}?fields=status_code&access_token={token}"
            with urllib.request.urlopen(u, timeout=30) as r:
                status = json.loads(r.read()).get("status_code", "IN_PROGRESS")
            if status in ("FINISHED", "ERROR", "EXPIRED"):
                break
        if status != "FINISHED":
            raise RuntimeError(f"conteneur non prêt ({status})")
        data = urllib.parse.urlencode({"creation_id": container, "access_token": token}).encode()
        req = urllib.request.Request(f"{api}/{user_id}/media_publish", data=data)
        with urllib.request.urlopen(req, timeout=60) as r:
            media_id = json.loads(r.read())["id"]
        permalink = ""
        try:
            with urllib.request.urlopen(f"{api}/{media_id}?fields=permalink&access_token={token}", timeout=30) as r:
                permalink = json.loads(r.read()).get("permalink", "")
        except Exception:
            pass
        x("UPDATE posts SET status='published', published_at=?, permalink=? WHERE id=?",
          (now_iso(), permalink, post_id))
        log("info", f"Publié en direct : media {media_id}")
        return {"ok": True, "mode": "live", "permalink": permalink}
    except Exception as exc:
        x("UPDATE posts SET status='failed', error=? WHERE id=?", (str(exc)[:400], post_id))
        log("error", f"Échec de publication : {exc}")
        return {"ok": False, "error": str(exc)}


def publish_due():
    if setting("paused", "0") == "1":
        return []
    rows = q("SELECT id FROM posts WHERE status='queued' AND scheduled_for<=? ORDER BY scheduled_for",
             (datetime.now().replace(microsecond=0).isoformat(),))
    return [publish_post(r["id"]) for r in rows]


