def new_ref():
    d = datetime.now()
    return "ALP-" + d.strftime("%y%m%d") + "-" + secrets.token_hex(3).upper()


# --------------------------------------------------------------------------
# STRIPE — encaissement réel
# --------------------------------------------------------------------------
def stripe_key():
    """Clé secrète Stripe (sk_live_... ou sk_test_...).
    La variable d'environnement ALPENLICHT_STRIPE_KEY est prioritaire :
    elle survit aux redémarrages des hébergeurs sans disque persistant."""
    env_key = os.environ.get("ALPENLICHT_STRIPE_KEY", "").strip()
    if env_key.startswith("sk_"):
        return env_key
    return setting("stripe_secret_key", "").strip()


def stripe_diag():
    """État détaillé de la configuration Stripe, sans jamais révéler la clé."""
    brut = os.environ.get("ALPENLICHT_STRIPE_KEY", "")
    env_key = brut.strip()
    source = "absente"
    key = ""
    if env_key.startswith("sk_"):
        key, source = env_key, "environnement"
    else:
        key = setting("stripe_secret_key", "").strip()
        if key:
            source = "tableau de bord"
        elif env_key:
            source = "environnement invalide"
    prefixe = ""
    if key:
        morceaux = key.split("_")
        prefixe = "_".join(morceaux[:2]) + "_" if len(morceaux) >= 2 else key[:3]
    return {
        "source": source,
        "prefixe": prefixe,
        "longueur": len(key),
        "espace_ou_guillemet": brut != env_key or '"' in brut or "'" in brut,
        "url_publique": bool(setting("public_url", "").strip()),
        "derniere_erreur": setting("stripe_last_error", ""),
    }


def stripe_ready():
    """Stripe est utilisable si la clé ET une URL publique existent."""
    return bool(stripe_key() and setting("public_url", "").strip())


def _stripe_request(path, params=None, method="POST", timeout=25):
    """Appelle l'API Stripe et renvoie (code, dict)."""
    key = stripe_key()
    if not key:
        return 0, {"error": {"message": "Aucune clé Stripe enregistrée."}}
    payload = urllib.parse.urlencode(params or {}, doseq=True).encode() if params else None
    req = urllib.request.Request(f"{STRIPE_BASE}{path}", data=payload, method=method)
    req.add_header("Authorization", f"Bearer {key}")
    if payload:
        req.add_header("Content-Type", "application/x-www-form-urlencoded")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, json.loads(resp.read().decode("utf-8", "replace") or "{}")
    except urllib.error.HTTPError as exc:
        try:
            body = json.loads(exc.read().decode("utf-8", "replace") or "{}")
        except Exception:
            body = {}
        return exc.code, body
    except Exception as exc:
        return 0, {"error": {"message": str(exc)}}


def stripe_error_text(body):
    """Extrait un message lisible d'une erreur Stripe."""
    err = (body or {}).get("error") or {}
    return err.get("message") or (body or {}).get("message") or "Erreur inconnue de Stripe"


def stripe_create_checkout(order, product):
    """Crée une session de paiement Stripe et renvoie son URL."""
    public = setting("public_url", "").rstrip("/")
    success = (f"{public}/merci?ref={order['ref']}&token={order['license_token']}"
               "&session_id={CHECKOUT_SESSION_ID}")
    params = {
        "mode": "payment",
        "payment_method_types[0]": "card",
        "line_items[0][quantity]": "1",
        "line_items[0][price_data][currency]": CURRENCY.lower(),
        "line_items[0][price_data][unit_amount]": str(order["amount_cents"]),
        "line_items[0][price_data][product_data][name]": product["title"],
        "line_items[0][price_data][product_data][description]":
            "Fichier haute résolution + licence personnelle. Téléchargement immédiat après paiement.",
        "success_url": success,
        "cancel_url": f"{public}/p/{product['slug']}",
        "metadata[ref]": order["ref"],
        "client_reference_id": order["ref"],
        "locale": "fr",
    }
    email = (order.get("buyer_email") or "").strip()
    if email and "@" in email:
        params["customer_email"] = email

    code, body = _stripe_request("/v1/checkout/sessions", params)
    if code == 200 and body.get("url"):
        x("UPDATE orders SET source='stripe' WHERE ref=?", (order["ref"],))
        x("UPDATE orders SET license_token=? WHERE ref=?", (order["license_token"], order["ref"]))
        set_setting(f"stripe_session_{order['ref']}", body.get("id", ""))
        log("info", f"Session Stripe créée pour {order['ref']}")
        return body["url"], None
    msg = stripe_error_text(body)
    log("error", f"Stripe : {msg}")
    return None, msg


def stripe_verify_session(session_id, ref):
    """Demande à Stripe si la session est réellement payée. Renvoie True/False."""
    if not session_id or not stripe_key():
        return False
    code, body = _stripe_request(f"/v1/checkout/sessions/{session_id}", method="GET")
    if code != 200:
        log("error", f"Vérification Stripe impossible : {stripe_error_text(body)}")
        return False
    if (body.get("metadata") or {}).get("ref") not in (None, ref):
        log("error", f"Session Stripe {session_id} ne correspond pas à {ref}")
        return False
    return body.get("payment_status") == "paid"


def create_order(product_row, email="", source="demo"):
    ref, token = new_ref(), secrets.token_urlsafe(20)
    x("INSERT INTO orders(ref,product_id,amount_cents,currency,status,source,buyer_email,"
      "license_token,created_at) VALUES(?,?,?,?, 'pending', ?,?,?,?)",
      (ref, product_row["id"], product_row["price_cents"], CURRENCY, source, email, token, now_iso()))
    log("info", f"Commande créée {ref} — {product_row['title']}")
    return q1("SELECT * FROM orders WHERE ref=?", (ref,))


def mark_paid(ref, source=None):
    order = q1("SELECT * FROM orders WHERE ref=?", (ref,))
    if not order or order["status"] == "paid":
        return order
    if source:
        x("UPDATE orders SET status='paid', paid_at=?, source=? WHERE ref=?", (now_iso(), source, ref))
    else:
        x("UPDATE orders SET status='paid', paid_at=? WHERE ref=?", (now_iso(), ref))
    log("info", f"Paiement encaissé {ref} — {order['amount_cents'] / 100:.2f} {CURRENCY}")
    return q1("SELECT * FROM orders WHERE ref=?", (ref,))


def revenue_kpis():
    def scalar(sql):
        row = q1(sql)
        v = list(row.values())[0] if row else 0
        return round((v or 0) / 100, 2)

    return {
        "today": scalar("SELECT COALESCE(SUM(amount_cents),0) FROM orders WHERE status='paid' AND date(paid_at)=date('now','localtime')"),
        "today_count": (q1("SELECT COUNT(*) c FROM orders WHERE status='paid' AND date(paid_at)=date('now','localtime')") or {"c": 0})["c"],
        "d7": scalar("SELECT COALESCE(SUM(amount_cents),0) FROM orders WHERE status='paid' AND paid_at>=datetime('now','-7 days')"),
        "d30": scalar("SELECT COALESCE(SUM(amount_cents),0) FROM orders WHERE status='paid' AND paid_at>=datetime('now','-30 days')"),
        "total": scalar("SELECT COALESCE(SUM(amount_cents),0) FROM orders WHERE status='paid'"),
        "refunded": scalar("SELECT COALESCE(SUM(amount_cents),0) FROM orders WHERE status='refunded'"),
        "paid": (q1("SELECT COUNT(*) c FROM orders WHERE status='paid'") or {"c": 0})["c"],
        "pending": (q1("SELECT COUNT(*) c FROM orders WHERE status='pending'") or {"c": 0})["c"],
        "aov": scalar("SELECT COALESCE(AVG(amount_cents),0) FROM orders WHERE status='paid'"),
    }


def revenue_series(days=30):
    rows = q("SELECT date(paid_at) d, SUM(amount_cents) c, COUNT(*) n FROM orders "
             "WHERE status='paid' AND paid_at>=datetime('now', ?) GROUP BY date(paid_at)",
             (f"-{days} days",))
    by_day = {r["d"]: r for r in rows}
    out = []
    today = datetime.now().date()
    for i in range(days - 1, -1, -1):
        day = (today - timedelta(days=i)).isoformat()
        r = by_day.get(day)
        out.append({"date": day, "amount": round((r["c"] or 0) / 100, 2) if r else 0.0,
                    "orders": int(r["n"]) if r else 0})
    return out


# --------------------------------------------------------------------------
# AMORÇAGE
# --------------------------------------------------------------------------
def seed():
    known = {row["slug"] for row in q("SELECT slug FROM products")}
    added = 0
    for slug, title, kind, price, img, desc in PRODUCTS:
        if slug in known:
            # garde le catalogue à jour (titre, prix, texte, image) sans toucher aux ventes
            x("UPDATE products SET title=?, price_cents=?, description=?, image_key=? WHERE slug=?",
              (title, price, desc, img, slug))
            continue
        x("INSERT INTO products(slug,title,kind,price_cents,currency,description,image_key,created_at) "
          "VALUES(?,?,?,?,?,?,?,?)", (slug, title, kind, price, CURRENCY, desc, img, now_iso()))
        added += 1
    if added:
        total = (q1("SELECT COUNT(*) c FROM products") or {"c": 0})["c"]
        log("info", f"Catalogue : {added} produit(s) ajouté(s), {total} au total")

    if (q1("SELECT COUNT(*) c FROM orders") or {"c": 0})["c"] == 0:
        seed_orders()

    if (q1("SELECT COUNT(*) c FROM posts") or {"c": 0})["c"] == 0:
        ensure_queue()
        log("info", "File de publication initialisée")


def seed_orders(days=45):
    """Historique de démonstration, pour que le tableau de bord soit vivant."""
    prods = q("SELECT * FROM products")
    if not prods:
        return
    seed_val = 20261027
    count = 0
    for i in range(days, -1, -1):
        day = datetime.now() - timedelta(days=i)
        weekend = day.weekday() >= 5
        base = (1.2 + (days - i) / days * 2.2) * (1.4 if weekend else 1.0)
        if i == 0:
            base *= 0.6
        seed_val = (seed_val * 1103515245 + 12345) % (2 ** 31)
        n = max(0, int(base + ((seed_val % 1000) / 1000 - 0.5) * 1.8))
        for _ in range(n):
            seed_val = (seed_val * 1103515245 + 12345) % (2 ** 31)
            prod = prods[seed_val % len(prods)]
            paid = day.replace(hour=min(22, 7 + (seed_val % 15)), minute=seed_val % 60, second=0,
                              microsecond=0)
            if paid > datetime.now():
                continue
            ref = "ALP-" + paid.strftime("%y%m%d") + "-" + secrets.token_hex(3).upper()
            try:
                x("INSERT INTO orders(ref,product_id,amount_cents,currency,status,source,buyer_email,"
                  "license_token,created_at,paid_at) VALUES(?,?,?,?, 'paid', ?,?,?,?,?)",
                  (ref, prod["id"], prod["price_cents"], CURRENCY,
                   "demo" if seed_val % 10 < 7 else "manual",
                   f"client{seed_val % 900 + 100}@example.com", secrets.token_urlsafe(16),
                   paid.isoformat(), (paid + timedelta(minutes=2)).isoformat()))
                count += 1
            except sqlite3.IntegrityError:
                pass
    if count:
        log("warning", f"{count} commandes de DÉMONSTRATION insérées (source='demo').")


def reset_demo_orders():
    x("DELETE FROM orders")
    seed_orders()


