def view_shop():
    prods = q("SELECT * FROM products WHERE active=1 ORDER BY kind DESC, price_cents")
    photos = [p for p in prods if p["kind"] == "photo"]
    guides = [p for p in prods if p["kind"] == "guide"]

    def card(p):
        cover = " cover" if p["kind"] == "guide" else ""
        overlay = ""
        if p["kind"] == "guide":
            overlay = (f'<span class="cov"><span class="cov-k">Guide · {esc(APP_NAME)}</span>'
                       f'<span class="cov-t">{esc(p["title"])}</span></span>')
        return f"""<article class="card">
  <a class="ph{cover}" href="/p/{p['slug']}"><img src="/img/{p['image_key']}" alt="">
    <span class="tag">{'Guide PDF' if p['kind'] == 'guide' else 'Tirage'}</span>{overlay}</a>
  <div class="bd"><h3><a href="/p/{p['slug']}">{esc(p['title'])}</a></h3>
    <div class="desc">{esc(p['description'][:118])}{'…' if len(p['description']) > 118 else ''}</div>
    <div class="ft"><span class="price">{money(p['price_cents'])}</span>
      <a class="btn ghost" href="/p/{p['slug']}" style="padding:8px 14px;font-size:10px">Voir</a></div></div>
</article>"""

    body = f"""
<section class="hero"><div class="wrap in">
  <div>
    <div class="eyebrow" style="color:rgba(245,242,234,.5)">Paysages suisses · tirages &amp; guides</div>
    <h1>La Suisse,<br>en lumière naturelle.</h1>
    <p>Des paysages des Alpes et du Jura, composés un par un, publiés chaque jour sur Instagram.
       Tirages d'art numériques et guides de randonnée, livrés immédiatement après paiement.</p>
    <div class="k"><div><b>{len(prods)}</b> produits</div><div><b>4:5</b> haute résolution</div>
      <div><b>PDF</b> livraison instantanée</div></div>
  </div>
  <div class="hero-art"><img src="/img/matterhorn" alt="Le Cervin à l'heure dorée">
    <div class="lbl">Le Cervin · Valais</div></div>
</div></section>
<div class="wrap">
  <section class="cat"><div class="eyebrow">Tirages d'art</div>
    <h2>Images à imprimer, grand format</h2>
    <p class="note">Fichiers 1080 × 1350 px et versions haute résolution, licence personnelle incluse.
       Impression jusqu'à 60 × 75 cm.</p>
    <div class="grid">{''.join(card(p) for p in photos)}</div></section>
  <section class="cat"><div class="eyebrow">Guides numériques</div>
    <h2>Randonner et photographier</h2>
    <p class="note">Itinéraires testés, horaires de lumière, recettes de post-traitement. PDF immédiat.</p>
    <div class="grid">{''.join(card(p) for p in guides)}</div></section>
  <div class="trust">
    <div><b>Paiement</b>Lien sécurisé, carte bancaire. Aucune donnée de paiement stockée ici.</div>
    <div><b>Livraison</b>Lien de téléchargement personnel immédiatement après validation.</div>
    <div><b>Licence</b>Usage personnel, impression libre. Revente interdite.</div>
    <div><b>Images IA</b>Contenus générés par intelligence artificielle, retouchés par l'auteur.</div>
  </div>
</div>"""
    return page("Boutique", body)


def view_product(slug):
    p = q1("SELECT * FROM products WHERE slug=?", (slug,))
    if not p:
        return None
    sold = q1("SELECT COUNT(*) c FROM orders WHERE product_id=? AND status='paid'", (p["id"],))["c"]
    TIRAGE = "Tirage d&#39;art"
    body = f"""
<div class="wrap"><div class="pdp">
  <div class="visual"><img src="/img/{p['image_key']}" alt="">
    <div style="display:flex;justify-content:space-between;padding:10px 14px;font-size:10px;letter-spacing:.12em;
    text-transform:uppercase;color:var(--muted)">
      <span>{'Tirage numérique' if p['kind'] == 'photo' else 'Guide PDF'}</span><span>1080 × 1350 px</span></div></div>
  <div>
    <div class="eyebrow">{TIRAGE if p['kind'] == 'photo' else 'Guide numérique'}</div>
    <h1>{esc(p['title'])}</h1>
    <p class="lead">{esc(p['description'])}</p>
    <div class="pricebox"><div class="p">{money(p['price_cents'])}</div>
      <div class="note">{sold} exemplaire{'s' if sold != 1 else ''} vendu{'s' if sold != 1 else ''} ·
        TVA incluse · téléchargement immédiat</div></div>
    <form class="buyform" method="post" action="/buy/{p['slug']}">
      <div><label>Votre e-mail (pour le reçu)</label>
        <input type="email" name="email" placeholder="vous@exemple.ch" value="client@example.com" required></div>
      <button class="btn red" type="submit">Acheter — {money(p['price_cents'])}</button>
      <div class="note">Paiement traité par notre prestataire sécurisé. Lien de téléchargement dès validation.</div>
    </form>
    <ul class="usp"><li>Résolution haute définition, prête à imprimer</li>
      <li>Licence personnelle incluse</li>
      {'<li>PDF A5, lisible sur téléphone et imprimable</li>' if p['kind'] == 'guide' else ''}
      <li>Image générée par IA, retouchée à la main</li></ul>
  </div>
</div>
<p class="note" style="margin-top:18px"><a href="/" style="text-decoration:underline">← Retour à la boutique</a></p>
</div>"""
    return page(p["title"], body)


def view_checkout(ref):
    o = q1("SELECT o.*, p.title, p.image_key, p.slug FROM orders o LEFT JOIN products p ON p.id=o.product_id "
           "WHERE o.ref=?", (ref,))
    if not o:
        return None
    body = f"""
<div class="wrap"><div class="pay">
  <div class="sum">
    <div class="eyebrow">Récapitulatif</div>
    <img src="/img/{o['image_key']}" alt="">
    <div style="font-family:Georgia,serif;font-size:17px">{esc(o['title'])}</div>
    <div class="ref" style="margin-top:5px">Réf. {o['ref']}</div>
    <div style="margin-top:16px">
      <div class="row"><span>Sous-total</span><span>{money(o['amount_cents'])}</span></div>
      <div class="row"><span>Livraison numérique</span><span>Incluse</span></div>
      <div class="row"><span>TVA</span><span>Incluse</span></div>
      <div class="tot"><span>Total</span><span>{money(o['amount_cents'])}</span></div>
    </div>
  </div>
  <div class="form">
    <h2 style="font-family:-apple-system,sans-serif;font-size:14.5px;margin:0 0 12px">Paiement par carte</h2>
    <div class="sandbox"><b>Tunnel de démonstration.</b> Aucun débit réel. En production, un lien
      Stripe / PayPal remplace cet écran (réglable dans le tableau de bord).</div>
    <form method="post" action="/pay/{o['ref']}">
      <label style="display:block;margin-bottom:5px">E-mail</label>
      <input type="email" name="email" value="{esc(o['buyer_email'] or 'client@example.com')}"
             style="margin-bottom:12px" required>
      <label style="display:block;margin-bottom:5px">Carte bancaire</label>
      <div class="cardfield"><div class="top"><span>4242 4242 4242 4242</span><span style="color:#888">VISA</span></div>
        <div class="bot"><div>12 / 30</div><div>CVC · 123</div></div></div>
      <button class="btn red" style="width:100%" type="submit">Payer {money(o['amount_cents'])}</button>
      <div class="note" style="margin-top:12px">🔒 Paiement chiffré · aucune donnée bancaire stockée.</div>
    </form>
  </div>
</div></div>"""
    return page("Paiement", body)


def view_merci(ref):
    o = q1("SELECT o.*, p.title, p.image_key, p.slug FROM orders o LEFT JOIN products p ON p.id=o.product_id "
           "WHERE o.ref=?", (ref,))
    if not o:
        return None
    paid = o["status"] == "paid"
    dl = ""
    if paid:
        dl = (f'<a class="btn" href="/download/{o["ref"]}?token={o["license_token"]}">Télécharger</a>')
    body = f"""
<div class="wrap"><div class="thanks">
  <div class="check">{'✓' if paid else '!'}</div>
  <h1>{'Merci pour votre achat.' if paid else 'Paiement en attente'}</h1>
  <p class="note">{'Paiement confirmé. Votre fichier est disponible immédiatement.'
                   if paid else "Nous n'avons pas encore reçu la confirmation du prestataire."}</p>
  <div class="dl"><div class="row">
    <img src="/img/{o['image_key']}" alt="">
    <div style="flex:1"><b>{esc(o['title'])}</b>
      <div class="note">{money(o['amount_cents'])} · licence personnelle</div>
      <div class="ref">Réf. {o['ref']}</div></div>
    {dl}</div></div>
  <p class="note" style="margin-top:26px">
    <a href="/" style="text-decoration:underline">Retour à la boutique</a> ·
    <a href="/dashboard" style="text-decoration:underline">Voir le revenu dans le tableau de bord</a></p>
</div></div>"""
    return page("Merci", body)


def view_bio():
    prods = q("SELECT * FROM products WHERE active=1 ORDER BY kind DESC, price_cents")
    links = "".join(
        f"""<a href="/p/{p['slug']}"><img class="th" src="/img/{p['image_key']}" alt="">
        <div class="t"><b>{esc(p['title'])}</b>
          <span>{'Tirage numérique' if p['kind'] == 'photo' else 'Guide PDF'} · livraison immédiate</span></div>
        <div class="pr">{money(p['price_cents'])}</div></a>""" for p in prods)
    body = f"""
<div class="wrap"><div class="bio">
  <div class="avatar"><img src="/img/matterhorn" alt=""></div>
  <h1>{esc(APP_NAME)}</h1>
  <div class="note">{esc(BRAND_TAGLINE)} · un paysage chaque jour</div>
  <div class="links">{links}
    <a href="/" style="justify-content:center;font-size:11px;letter-spacing:.15em;text-transform:uppercase">
      Voir toute la boutique</a></div>
  <div class="eyebrow" style="margin-top:24px">Images générées par IA · retouchées à la main</div>
</div></div>"""
    return page("Liens", body)


