# --------------------------------------------------------------------------
# PDF MINIMAL (guides et licence), sans dépendance
# --------------------------------------------------------------------------
def make_pdf(title, lines):
    """Construit un PDF valide avec la police Helvetica (bibliothèque standard)."""
    def esc_pdf(s):
        return s.replace("\\", r"\\").replace("(", r"\(").replace(")", r"\)")

    content = ["BT", "/F1 18 Tf", "1 0 0 1 56 770 Tm", f"({esc_pdf(title)}) Tj", "ET"]
    y = 740
    for line in lines:
        for chunk in [line[i:i + 90] for i in range(0, max(1, len(line)), 90)] or [""]:
            y -= 8
            if y < 60:
                break
            content += ["BT", "/F1 9 Tf", f"1 0 0 1 56 {y} Tm", f"({esc_pdf(chunk)}) Tj", "ET"]
    stream = "\n".join(content).encode("latin-1", "replace")

    objs = [
        b"<< /Type /Catalog /Pages 2 0 R >>",
        b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
        b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> "
        b"/Contents 4 0 R >>",
        b"<< /Length " + str(len(stream)).encode() + b" >>\nstream\n" + stream + b"\nendstream",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
    ]
    out = bytearray(b"%PDF-1.4\n")
    offsets = []
    for i, obj in enumerate(objs, start=1):
        offsets.append(len(out))
        out += f"{i} 0 obj\n".encode() + obj + b"\nendobj\n"
    xref = len(out)
    out += f"xref\n0 {len(objs) + 1}\n".encode() + b"0000000000 65535 f \n"
    for off in offsets:
        out += f"{off:010d} 00000 n \n".encode()
    out += (f"trailer\n<< /Size {len(objs) + 1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n").encode()
    return bytes(out)


def license_pdf(product_title):
    return make_pdf("Licence d'utilisation", [
        f"Oeuvre : {product_title}",
        "",
        "Droits accordes (licence personnelle, non exclusive, non transferable) :",
        "- Impression et affichage prive, y compris formats decoratifs.",
        "- Utilisation sur vos reseaux sociaux personnels avec mention de l'auteur.",
        "- Sauvegarde sur vos appareils.",
        "",
        "Interdits :",
        "- Revente, redistribution, mise a disposition en telechargement.",
        "- Usage commercial ou publicitaire sans licence etendue.",
        "- Revente d'impressions, reprise dans un produit derive.",
        "",
        "L'image est une creation generee par intelligence artificielle, retouchee par l'auteur.",
        "Aucune personne identifiable n'y figure.",
        "",
        f"{APP_NAME} - {CURRENCY}",
    ])


def guide_pdf(slug, title):
    lines = []
    for i, (head, body) in enumerate(GUIDE_TEXTS.get(slug, []), start=1):
        lines.append("")
        lines.append(f"{i}. {head}")
        lines.append(body)
    if not lines:
        lines = ["Ce guide est en preparation.", "", "Merci de votre confiance."]
    return make_pdf(title, lines)


# --------------------------------------------------------------------------
# SERVEUR HTTP
# --------------------------------------------------------------------------
class Handler(BaseHTTPRequestHandler):
    server_version = "Alpenlicht/1.0"

    def log_message(self, fmt, *args):
        pass  # console silencieuse

    # --- utilitaires ------------------------------------------------------
    def send_html(self, html, status=200):
        data = html.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Cache-Control", "no-store, must-revalidate")
        self.send_header("Pragma", "no-cache")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def send_json(self, payload, status=200):
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def redirect(self, location):
        self.send_response(303)
        self.send_header("Location", location)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def send_bytes(self, data, content_type, filename=None):
        self.send_response(200)
        self.send_header("Content-Type", content_type)
        if filename:
            self.send_header("Content-Disposition", f'attachment; filename="{filename}"')
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def read_body(self):
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length else b""
        ctype = (self.headers.get("Content-Type") or "").lower()
        if "application/json" in ctype:
            try:
                return json.loads(raw or b"{}")
            except json.JSONDecodeError:
                return {}
        return {k: v[0] for k, v in urllib.parse.parse_qs(raw.decode("utf-8")).items()}

    # --- protection du tableau de bord -----------------------------------
    LOCAL_HOSTS = {"localhost", "127.0.0.1", "::1"}

    def is_local_request(self):
        host = (self.headers.get("Host") or "").split(":")[0].strip("[]").lower()
        return host in self.LOCAL_HOSTS

    def submitted_token(self, query):
        tok = (query.get("token") or [""])[0]
        if tok:
            return tok
        cookie = self.headers.get("Cookie") or ""
        for part in cookie.split(";"):
            name, _, value = part.strip().partition("=")
            if name == "alp_admin":
                return value
        return ""

    def guard(self, query, redirect_after=""):
        """Renvoie True si l'accès est autorisé, sinon envoie la réponse de refus."""
        if not PROTECT_DASHBOARD:
            return True
        token = admin_token()
        given = self.submitted_token(query)
        if given and secrets.compare_digest(given, token):
            if (query.get("token") or [""])[0]:
                body = b""
                self.send_response(303)
                self.send_header("Location", redirect_after or "/dashboard")
                self.send_header("Set-Cookie", f"alp_admin={token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=2592000")
                self.send_header("Content-Length", "0")
                self.end_headers()
                return "redirect"
            return True
        if self.is_local_request():
            return True
        self.send_html(login_page(), 401)
        return False

    # --- GET --------------------------------------------------------------
    def do_GET(self):
        try:
            path = urllib.parse.urlparse(self.path).path
            query = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)

            if path.startswith("/img/"):
                key = path.split("/")[-1].split(".")[0]
                data = IMAGES.get(key)
                if not data:
                    return self.send_html("Image introuvable", 404)
                return self.send_bytes(data, "image/jpeg")

            if path in ("/", "/shop"):
                return self.send_html(view_shop())
            if path == "/dashboard":
                if self.guard(query, "/dashboard") is not True:
                    return
                return self.send_html(view_dashboard())
            if path == "/bio":
                return self.send_html(view_bio())
            if path == "/legal":
                return self.send_html(view_legal())
            if path.startswith("/p/"):
                html = view_product(path[3:])
                return self.send_html(html) if html else self.send_html("Produit introuvable", 404)
            if path.startswith("/checkout/"):
                html = view_checkout(path.split("/")[-1])
                return self.send_html(html) if html else self.send_html("Commande introuvable", 404)
            if path == "/merci":
                ref = (query.get("ref") or [""])[0]
                session_id = (query.get("session_id") or [""])[0]
                if ref and session_id and stripe_key():
                    order = q1("SELECT * FROM orders WHERE ref=?", (ref,))
                    if order and order["status"] != "paid" and stripe_verify_session(session_id, ref):
                        mark_paid(ref, "stripe")
                        set_setting(f"stripe_session_{ref}", session_id)
                html = view_merci(ref)
                return self.send_html(html) if html else self.send_html("Commande introuvable", 404)

            if path.startswith("/download/"):
                ref = path.split("/")[-1]
                token = (query.get("token") or [""])[0]
                order = q1("SELECT o.*, p.slug, p.title, p.kind FROM orders o "
                           "LEFT JOIN products p ON p.id=o.product_id WHERE o.ref=?", (ref,))
                if not order or order["license_token"] != token:
                    return self.send_html("Lien invalide", 403)
                if order["status"] != "paid":
                    return self.send_html("Paiement non confirmé", 402)
                if order["kind"] == "guide":
                    data = guide_pdf(order["slug"], order["title"])
                    return self.send_bytes(data, "application/pdf", f"{order['slug']}.pdf")
                data = license_pdf(order["title"])
                return self.send_bytes(data, "application/pdf", f"licence-{order['slug']}.pdf")

            if path.startswith("/api/"):
                if self.guard(query) is not True:
                    return

            if path == "/api/stats":
                return self.send_json(self.stats())

            if path == "/motdepasse":
                if not self.is_local_request():
                    return self.send_html("Page réservée à l'ordinateur du studio.", 403)
                return self.send_html(
                    "<!doctype html><meta charset='utf-8'>"
                    "<body style='background:#0f0e0c;color:#efe9e0;font-family:system-ui;"
                    "display:grid;place-items:center;height:100vh;margin:0;text-align:center'>"
                    "<div><div style='font-size:11px;letter-spacing:.24em;color:#b3392f;"
                    "text-transform:uppercase;margin-bottom:14px'>Alpenlicht Studio</div>"
                    "<div style='font-size:13px;color:#a49c90;margin-bottom:10px'>"
                    "Mot de passe du tableau de bord</div>"
                    f"<div style='font-size:34px;letter-spacing:.14em'>{admin_token()}</div>"
                    "<div style='font-size:12px;color:#6f6860;margin-top:16px'>"
                    "Visible seulement sur cet ordinateur.</div></div></body>")

            if path == "/health":
                return self.send_json({"ok": True, "app": "alpenlicht", "version": VERSION,
                                       "catalogue": CATALOGUE_COUNT[0],
                                       "mode": "live" if stripe_ready() else "demo",
                                       "paiement": stripe_diag()})

            return self.send_html("Page introuvable — <a href='/'>retour à la boutique</a>", 404)
        except Exception:
            traceback.print_exc()
            return self.send_html("Erreur interne — voir la console", 500)

    # --- POST -------------------------------------------------------------
    def do_POST(self):
        try:
            path = urllib.parse.urlparse(self.path).path
            form = self.read_body()

            if path.startswith("/buy/"):
                prod = q1("SELECT * FROM products WHERE slug=?", (path[5:],))
                if not prod:
                    return self.send_html("Produit introuvable", 404)
                source = "stripe" if stripe_ready() else "demo"
                order = create_order(prod, email=(form.get("email") or ""), source=source)
                if source == "stripe":
                    url, err = stripe_create_checkout(order, prod)
                    if url:
                        return self.redirect(url)
                    set_setting("stripe_last_error", str(err)[:300])
                    log("error", f"Repli sur le paiement de démonstration : {err}")
                return self.redirect(f"/checkout/{order['ref']}")

            if path.startswith("/pay/"):
                ref = path.split("/")[-1]
                order = q1("SELECT * FROM orders WHERE ref=?", (ref,))
                if not order:
                    return self.send_html("Commande introuvable", 404)
                email = form.get("email")
                if email:
                    x("UPDATE orders SET buyer_email=? WHERE ref=?", (email, ref))
                mark_paid(ref, "demo")
                return self.redirect(f"/merci?ref={ref}")

            if path.startswith("/api/"):
                query = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                if self.guard(query) is not True:
                    return

            if path == "/api/stats":
                return self.send_json(self.stats())

            if path == "/api/sell":
                prods = q("SELECT * FROM products WHERE active=1")
                if not prods:
                    return self.send_json({"ok": False, "error": "Aucun produit"})
                prod = prods[int(time.time()) % len(prods)]
                order = create_order(prod, source="demo")
                mark_paid(order["ref"], "demo")
                return self.send_json({"ok": True, "ref": order["ref"], "product": prod["title"],
                                       "amount": prod["price_cents"] / 100})

            if path == "/api/publish-now":
                plan = plan_for(datetime.now().strftime("%Y-%m-%d-%H%M%S"),
                                avoid=recent_locations(6))
                loc = plan["loc"]
                pid = x("INSERT INTO posts(location_key,location_name,canton,caption,scheduled_for,status,created_at) "
                        "VALUES(?,?,?,?,?, 'queued', ?)",
                        (loc["key"], loc["name"], loc["canton"], build_caption(plan),
                         datetime.now().replace(microsecond=0).isoformat(), now_iso()))
                return self.send_json(publish_post(pid))

            if path.startswith("/api/post/"):
                parts = path.split("/")
                pid, action = int(parts[3]), parts[4]
                if action == "publish":
                    return self.send_json(publish_post(pid))
                if action == "skip":
                    x("UPDATE posts SET status='skipped' WHERE id=? AND status='queued'", (pid,))
                    return self.send_json({"ok": True})
                if action == "retry":
                    x("UPDATE posts SET status='queued' WHERE id=? AND status='failed'", (pid,))
                    return self.send_json({"ok": True})

            if path.startswith("/api/order/"):
                parts = path.split("/")
                ref, action = parts[3], parts[4]
                if action == "paid":
                    mark_paid(ref, "manual")
                elif action == "refund":
                    x("UPDATE orders SET status='refunded' WHERE ref=?", (ref,))
                    log("warning", f"Commande {ref} remboursée")
                return self.send_json({"ok": True})

            if path == "/api/fill":
                return self.send_json({"ok": True, "created": ensure_queue()})

            if path == "/api/retry":
                rows = q("SELECT id FROM posts WHERE status='failed'")
                for r in rows:
                    x("UPDATE posts SET status='queued' WHERE id=?", (r["id"],))
                return self.send_json({"ok": True, "recovered": len(rows)})

            if path == "/api/pause":
                paused = setting("paused", "0") == "1"
                set_setting("paused", "0" if paused else "1")
                log("warning", "Automatisation reprise" if paused else "Automatisation en PAUSE")
                return self.send_json({"ok": True, "paused": not paused})

            if path == "/api/settings":
                if form.get("token"):
                    set_setting("ig_token", form["token"])
                if form.get("user_id"):
                    set_setting("ig_user_id", form["user_id"])
                if form.get("public_url"):
                    set_setting("public_url", form["public_url"].rstrip("/"))
                if form.get("stripe_key"):
                    key = str(form["stripe_key"]).strip()
                    if key.startswith("sk_"):
                        set_setting("stripe_secret_key", key)
                        log("info", "Clé Stripe enregistrée (mode "
                                    + ("test" if key.startswith("sk_test") else "réel") + ")")
                    else:
                        return self.send_json({"ok": False,
                                               "error": "La clé doit commencer par sk_"}, 400)
                if form.get("stripe_key") == "":
                    return self.send_json({"ok": False, "error": "Clé vide"}, 400)
                log("info", "Identifiants Instagram mis à jour")
                return self.send_json({"ok": True})

            if path.startswith("/api/product/"):
                pid = int(path.split("/")[-1])
                if form.get("price"):
                    try:
                        x("UPDATE products SET price_cents=? WHERE id=?",
                          (int(float(str(form["price"]).replace(",", ".")) * 100), pid))
                    except ValueError:
                        pass
                if "payment_url" in form:
                    x("UPDATE products SET payment_url=? WHERE id=?", (form["payment_url"], pid))
                return self.send_json({"ok": True})

            return self.send_json({"ok": False, "error": "Route inconnue"}, 404)
        except Exception:
            traceback.print_exc()
            return self.send_json({"ok": False, "error": "Erreur interne"}, 500)

    # --- agrégats ---------------------------------------------------------
    def stats(self):
        counts = {r["status"]: r["n"] for r in q("SELECT status, COUNT(*) n FROM posts GROUP BY status")}
        posts = q("SELECT * FROM posts ORDER BY "
                  "CASE status WHEN 'queued' THEN 0 ELSE 1 END, scheduled_for DESC LIMIT 12")
        orders = q("SELECT o.*, p.title FROM orders o LEFT JOIN products p ON p.id=o.product_id "
                   "ORDER BY COALESCE(o.paid_at, o.created_at) DESC LIMIT 12")
        pending = q("SELECT o.*, p.title FROM orders o LEFT JOIN products p ON p.id=o.product_id "
                    "WHERE o.status='pending' ORDER BY o.created_at DESC LIMIT 10")
        products = q("SELECT p.*, "
                     "(SELECT COUNT(*) FROM orders o WHERE o.product_id=p.id AND o.status='paid') sales, "
                     "(SELECT COALESCE(SUM(amount_cents),0) FROM orders o WHERE o.product_id=p.id "
                     "AND o.status='paid') revenue_cents FROM products p ORDER BY revenue_cents DESC")
        events = q("SELECT level, message, created_at FROM events ORDER BY id DESC LIMIT 14")
        queued = counts.get("queued", 0)
        return {
            "kpis": revenue_kpis(),
            "series": revenue_series(30),
            "posts": posts,
            "counts": {"queued": queued, "published": counts.get("published", 0),
                       "failed": counts.get("failed", 0)},
            "queue_days": queued,
            "orders": orders,
            "pending": pending,
            "products": products,
            "events": events,
            "paused": setting("paused", "0") == "1",
            "live": bool(setting("ig_token", IG_TOKEN) and setting("ig_user_id", IG_USER_ID)),
            "ig_user": setting("ig_user_id", IG_USER_ID),
        }


def scheduler_loop():
    """Publie les posts échus, une fois par minute."""
    while True:
        try:
            publish_due()
            ensure_queue()
        except Exception:
            traceback.print_exc()
        time.sleep(60)


def _server_ready(port, timeout=20.0):
    """Attend que le serveur accepte vraiment les connexions."""
    import socket

    end = time.time() + timeout
    while time.time() < end:
        try:
            with socket.create_connection(("127.0.0.1", port), timeout=1):
                return True
        except OSError:
            time.sleep(0.15)
    return False


def open_browser_when_ready(url, port):
    """Ouvre le navigateur, avec plusieurs méthodes de secours."""
    if os.environ.get("ALPENLICHT_NO_BROWSER"):
        return
    if not _server_ready(port):
        print("   [!] Le serveur ne répond pas encore. Ouvrez l'adresse à la main.")
        return

    attempts = []
    # 1) méthode standard
    attempts.append(("webbrowser", lambda: webbrowser.open(url, new=2)))
    # 2) Windows : association de fichiers du système
    if os.name == "nt":
        attempts.append(("os.startfile", lambda: os.startfile(url)))  # noqa: S606
        attempts.append(("cmd start", lambda: subprocess.Popen(
            ["cmd", "/c", "start", "", url],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))))
        attempts.append(("explorer", lambda: subprocess.Popen(
            ["explorer", url], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)))
    # 3) macOS / Linux
    if sys.platform == "darwin":
        attempts.append(("open", lambda: subprocess.Popen(["open", url])))
    else:
        attempts.append(("xdg-open", lambda: subprocess.Popen(
            ["xdg-open", url], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)))

    for name, method in attempts:
        try:
            result = method()
            if name == "webbrowser":
                if result is False:
                    continue
            print(f"   Navigateur lancé ({name}). Si rien ne s'affiche,")
            print(f"   copiez cette adresse dans Chrome, Edge ou Firefox :")
            print(f"      {url}")
            return
        except Exception:
            continue

    print("   [!] Impossible d'ouvrir le navigateur automatiquement.")
    print(f"   Copiez cette adresse dans Chrome, Edge ou Firefox :")
    print(f"      {url}")


def _port_free(port):
    import socket

    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        try:
            sock.bind(("127.0.0.1", port))
            return True
        except OSError:
            return False


def _running_version(port, timeout=2.0):
    """Renvoie la version de l'instance qui tourne déjà, ou None."""
    try:
        with urllib.request.urlopen(f"http://127.0.0.1:{port}/health", timeout=timeout) as resp:
            data = json.loads(resp.read().decode("utf-8", "replace") or "{}")
        if data.get("app") == "alpenlicht":
            return data.get("version") or "0"
    except Exception:
        pass
    return None


def choose_port(preferred, tries=25):
    """Renvoie (port, etat) avec etat = 'libre' | 'deja_lance' | 'autre_port'."""
    if _port_free(preferred):
        return preferred, "libre"
    running = _running_version(preferred)
    if running == VERSION:
        return preferred, "deja_lance"
    if running is not None:
        # une ancienne version occupe le port : on prend le suivant
        for candidate in range(preferred + 1, preferred + tries):
            if _port_free(candidate):
                return candidate, "ancienne_version"
        return preferred, "ancienne_version"
    for candidate in range(preferred + 1, preferred + tries):
        if _port_free(candidate):
            return candidate, "autre_port"
    return preferred, "libre"


def startup_menu():
    """Demande le mode de lancement, uniquement si la console est interactive."""
    if os.environ.get("ALPENLICHT_NO_MENU"):
        return
    try:
        if not sys.stdin or not sys.stdin.isatty():
            return
    except Exception:
        return
    print()
    print("=" * 58)
    print("   ALPENLICHT STUDIO")
    print("=" * 58)
    print()
    print("   1  -  Voir la boutique sur cet ordinateur   (le plus simple)")
    print("   2  -  Mettre la boutique EN LIGNE           (adresse publique)")
    print()
    try:
        choice = input("   Votre choix [1] : ").strip()
    except (EOFError, OSError, KeyboardInterrupt):
        choice = ""
    if choice == "2":
        PUBLIC_MODE["on"] = True
    print()


def main():
    startup_menu()
    port, etat = choose_port(PORT)
    url = f"http://localhost:{port}"
    try:
        with open(os.path.join(HERE, "port.txt"), "w", encoding="utf-8") as fh:
            fh.write(str(port))
    except OSError:
        pass

    if etat == "deja_lance":
        print()
        print(f"   Alpenlicht est DÉJÀ en marche sur {url}")
        print("   J'ouvre le navigateur sur cette page.")
        print()
        open_browser_when_ready(url, port)
        time.sleep(3)
        return

    init_db()
    seed()

    env_public = os.environ.get("ALPENLICHT_PUBLIC_URL", "").strip()
    if env_public and setting("public_url", "") != env_public.rstrip("/"):
        set_setting("public_url", env_public.rstrip("/"))


    print("=" * 58)
    print(f"   {APP_NAME.upper()} — {BRAND_TAGLINE}")
    print("=" * 58)
    print()
    if etat == "ancienne_version":
        print()
        print(f"   (une ancienne version d'Alpenlicht occupait déjà le port {PORT})")
        print(f"    La nouvelle version démarre sur le port {port}.")
        print("    Pensez à fermer l'ancienne fenêtre noire.")
        print()
    if etat == "autre_port":
        print(f"   (le port {PORT} était occupé par un autre programme,")
        print(f"    {port} a été choisi automatiquement)")
        print()
    print(f"   Boutique        {url}")
    print(f"   Tableau de bord {url}/dashboard")
    print(f"   Lien en bio     {url}/bio")
    print()
    n_prod = (q1("SELECT COUNT(*) c FROM products") or {"c": 0})["c"]
    n_photo = (q1("SELECT COUNT(*) c FROM products WHERE kind='photo'") or {"c": 0})["c"]
    print(f"   Version {VERSION} · catalogue : {n_prod} produits ({n_photo} tirages et packs)")
    if PROTECT_DASHBOARD:
        print(f"   Mot de passe du tableau de bord : {admin_token()}")
    else:
        print("   Tableau de bord : aucun mot de passe demande")
    print(f"   Base de données : {DB_PATH}")
    print("   Mode démonstration : publications et paiements simulés.")
    print()
    print("   >>> Laissez cette fenêtre ouverte. Ctrl+C pour arrêter.")
    print()
    print("   Si votre navigateur ne s'ouvre pas tout seul :")
    print(f"   ouvrez Chrome, Edge ou Firefox et tapez  {url}")
    print("=" * 58)
    print(flush=True)

    threading.Thread(target=scheduler_loop, daemon=True).start()

    try:
        server = ThreadingHTTPServer((HOST, port), Handler)
    except OSError:
        print(f"   [!] Impossible de démarrer sur le port {port}.")
        _pause()
        return

    if PUBLIC_MODE["on"] and HOST == "127.0.0.1":
        start_public_tunnel(port)

    threading.Thread(target=open_browser_when_ready, args=(url, port), daemon=True).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nArrêt du serveur. À bientôt.")
        server.shutdown()


def _cloudflared_path():
    """Cherche cloudflared à côté du programme ou dans le PATH."""
    if os.name == "nt":
        candidate = os.path.join(HERE, "cloudflared.exe")
        if os.path.exists(candidate):
            return candidate
    else:
        candidate = os.path.join(HERE, "cloudflared")
        if os.path.exists(candidate):
            return candidate
    import shutil
    return shutil.which("cloudflared")


def _download_cloudflared():
    """Télécharge cloudflared à côté du programme (une seule fois)."""
    name = "cloudflared.exe" if os.name == "nt" else "cloudflared"
    target = os.path.join(HERE, name)
    if os.path.exists(target):
        return target
    url = ("https://github.com/cloudflare/cloudflared/releases/latest/download/"
           + ("cloudflared-windows-amd64.exe" if os.name == "nt" else "cloudflared-linux-amd64"))
    print()
    print("   Téléchargement de l'outil de mise en ligne (40 Mo)...")
    print("   Cela ne se fait qu'une seule fois, merci de patienter.")
    tmp = target + ".part"
    try:
        with urllib.request.urlopen(url, timeout=120) as resp, open(tmp, "wb") as fh:
            total = int(resp.headers.get("Content-Length") or 0)
            done = 0
            while True:
                chunk = resp.read(262144)
                if not chunk:
                    break
                fh.write(chunk)
                done += len(chunk)
                if total:
                    pct = done * 100 // total
                    print(f"\r   {pct:3d} %  ({done // 1048576} / {total // 1048576} Mo)", end="", flush=True)
        print()
        os.replace(tmp, target)
        if os.name != "nt":
            os.chmod(target, 0o755)
        print("   Outil de mise en ligne prêt.")
        return target
    except Exception:
        print()
        print("   [!] Le téléchargement a échoué (connexion Internet ?).")
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except OSError:
            pass
        return None


def start_public_tunnel(port):
    """Ouvre un tunnel Cloudflare et affiche l'adresse publique."""
    exe = _cloudflared_path() or _download_cloudflared()
    if not exe:
        print()
        print("   [!] Impossible de préparer l'outil de mise en ligne.")
        print("       Vérifiez votre connexion puis relancez.")
        return None

    flags = 0
    if os.name == "nt":
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    try:
        proc = subprocess.Popen(
            [exe, "tunnel", "--url", f"http://localhost:{port}", "--no-autoupdate"],
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, errors="replace", bufsize=1, creationflags=flags,
        )
    except Exception:
        traceback.print_exc()
        print("   [!] Impossible de démarrer le tunnel.")
        return None

    def reader():
        import re
        pattern = re.compile(r"https://[a-z0-9-]+\.trycloudflare\.com")
        for line in proc.stdout:
            match = pattern.search(line)
            if match and not PUBLIC_URL["value"]:
                PUBLIC_URL["value"] = match.group(0)
                set_setting("public_url", match.group(0))
                print()
                print("=" * 58)
                print("   VOTRE BOUTIQUE EST EN LIGNE")
                print("=" * 58)
                print()
                print(f"   {match.group(0)}")
                print()
                print("   Envoyez cette adresse : elle marche sur")
                print("   téléphone, tablette, ordinateur, partout.")
                print("   (Elle change à chaque redémarrage.)")
                print()
                print(f"   Tableau de bord : {match.group(0)}/dashboard")
                if PROTECT_DASHBOARD:
                    print(f"   Mot de passe    : {admin_token()}")
                print()
                print("   ATTENTION : les paiements sont simulés, donc")
                print("   n'importe qui peut télécharger gratuitement.")
                print("   Pour vendre pour de vrai, il faut Stripe.")
                print("=" * 58)
                print(flush=True)

    threading.Thread(target=reader, daemon=True).start()
    return proc


def _pause():
    """Attend une touche, sans planter si la console n'est pas interactive."""
    try:
        input("\nAppuyez sur Entrée pour fermer...")
    except (EOFError, OSError):
        pass


if __name__ == "__main__":
    try:
        main()
    except OSError as exc:
        if "Address already in use" in str(exc) or getattr(exc, "errno", 0) in (48, 98):
            print()
            print(f"[!] Le port {PORT} est déjà utilisé.")
            print("    Une autre fenêtre Alpenlicht est probablement déjà ouverte.")
            print("    -> Si l'application fonctionne déjà, ouvrez simplement :")
            print(f"       http://localhost:{PORT}")
            print("    -> Sinon, lancez avec un autre port :")
            print(f"       set ALPENLICHT_PORT=8001")
            print(f"       python Alpenlicht.py")
        else:
            traceback.print_exc()
        _pause()
    except Exception:
        traceback.print_exc()
        _pause()

